 function dragStart(e:PointerEvent<HTMLDivElement>){if(e.button!==0||(e.target as HTMLElement).closest('button'))return;const r=dialog.current?.getBoundingClientRect();if(!r)return;e.currentTarget.setPointerCapture(e.pointerId);drag.current={x:e.clientX,y:e.clientY,left:r.left,top:r.top,width:r.width,height:r.height,ox:offset.x,oy:offset.y}}
 function dragMove(e:PointerEvent<HTMLDivElement>){const d=drag.current;if(!d)return;const dx=Math.max(8-d.left,Math.min(e.clientX-d.x,innerWidth-8-d.width-d.left));const dy=Math.max(8-d.top,Math.min(e.clientY-d.y,innerHeight-8-d.height-d.top));setOffset({x:d.ox+dx,y:d.oy+dy})}
 useEffect(()=>{setOffset({x:0,y:0});drag.current=null},[modal?.kind]);
 useEffect(()=>{const reset=()=>setOffset({x:0,y:0});window.addEventListener('resize',reset);return()=>window.removeEventListener('resize',reset)},[]);
 const dialog=useRef<HTMLDialogElement>(null),saving=useRef(false);
 async function load(){try{setError('');const d=await api({op:'bootstrap'});setData(d);setLoaded(true)}catch(e){setError((e as Error).message)}}
 useEffect(()=>{void load()},[]);
 useEffect(()=>{if(modal&&!dialog.current?.open)dialog.current?.showModal();if(!modal)dialog.current?.close()},[modal]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(timer)},[toast]);
 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();try{void Promise.resolve(ctx.registerTool({name:'read_island_diary',title:'섬 다이어리 읽기',description:'저장된 계획, 할 일, 실제 기록을 읽습니다. 변경하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('빈 객체를 입력해 주세요.');return await api()}},{signal:lifecycle.signal})).catch(()=>{})}catch{}return()=>lifecycle.abort()},[]);
 const plan=data.plans.find(p=>p.id===planId)||data.plans[0];const tasks=selectTasks(data,plan?.id||'');const period=selectTasks(data,plan?.id||'',from,to);const stats=reviewStats(data,period);const allStats=reviewStats(data,tasks);
 function choosePlan(id:string){setPlanId(id);const p=data.plans.find(p=>p.id===id);if(p){setFrom(p.start_date);setTo(p.end_date)}setDrill('');setSearch('');setFilter('all');setTag('all')}
 async function mutate(body:Row){if(saving.current)return false;saving.current=true;setBusy(true);setError('');try{const d=await api(body);setData(d);setToast('저장했어요.');return true}catch(e){setError((e as Error).message);return false}finally{saving.current=false;setBusy(false)}}
 function openTask(t?:Row){setModal({kind:t?'task-edit':'task-create',value:t?{...t}:{id:uid(),plan_id:plan.id,title:'',due_date:plan.end_date,priority:2,tags:'',estimate:60}})}
 function openLog(t?:Row,complete=false){const chosen=t||tasks[0];if(!chosen){setToast('먼저 할 일을 하나 만들어 주세요.');return}setModal({kind:'execution',value:{id:uid(),task_id:chosen.id,start_at:'',end_at:'',blocked:'',note:'',complete,cycle:chosen.cycle}})}
 function editLog(e:Row){setModal({kind:'execution-edit',value:{...e,start_at:kstInput(new Date(e.start_at)),end_at:kstInput(new Date(e.end_at)),original:{start_at:e.start_at,end_at:e.end_at,blocked:e.blocked,note:e.note}}})}
 function change(key:string,value:unknown){setModal(m=>m?{...m,value:{...m.value,[key]:value}}:null)}
 async function submit(e:FormEvent){e.preventDefault();if(!modal)return;let value={...modal.value};if(modal.kind.startsWith('execution')){value.start_at=new Date(value.start_at+':00+09:00').toISOString();value.end_at=new Date(value.end_at+':00+09:00').toISOString()}
 let body:Row={op:modal.kind,value};if(modal.kind==='review')body={op:'review',value:{id:value.review_id,plan_id:plan.id,start_date:from,end_date:to,improvement:value.improvement,next:value}};
 if(await mutate(body)){setModal(null);if(modal.kind==='plan-create'||modal.kind==='review'){setPlanId(value.id);setFrom(value.start_date);setTo(value.end_date);setTab(0)}}}
 async function openRoutine(){if(await mutate({op:'daily-routine',date:routineDate})){setPlanId('daily-routine-'+routineDate);setFrom(routineDate);setTo(routineDate);setTab(0);setSearch('');setFilter('all');setPrio('all');setTag('all');setDrill('')}}
 async function exportAll(){try{const latest=await api();setData(latest);const blob=new Blob([JSON.stringify({schema:'pds-schema-v2',exported_at:new Date().toISOString(),timezone:'Asia/Seoul',time_unit:'minute',...latest},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='큐티스트릿도-전체기록.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){setError((e as Error).message)}}
 const visible=tasks.filter(t=>(t.title+' '+t.tags).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||(filter==='done'?t.status==='done':filter==='late'?t.status!=='done'&&t.due_date<seoulToday():t.status==='open'))&&(prio==='all'||t.priority===Number(prio))&&(tag==='all'||t.tags.split(',').map((s:string)=>s.trim()).includes(tag))).sort((a,b)=>(sort==='priority'?a.priority-b.priority:sort==='estimate'?a.estimate-b.estimate:a.due_date.localeCompare(b.due_date))||a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id));
 const tags=[...new Set(tasks.flatMap(t=>t.tags.split(',').map((s:string)=>s.trim()).filter(Boolean)))];
 const records=data.executions.filter(e=>tasks.some(t=>t.id===e.task_id)).sort((a,b)=>b.start_at.localeCompare(a.start_at)||a.id.localeCompare(b.id));
 const drillTasks=period.filter(t=>drill==='done'?t.status==='done':drill==='late'?t.status!=='done'&&t.due_date<seoulToday():drill==='blocked'?stats.records.some(e=>e.task_id===t.id&&e.blocked.trim()):true);
 const labels:Record<string,string>={planned:'계획한 할 일',done:'완료',late:'지연',blocked:'막힘',estimate:'예상 시간',actual:'기록별 시간 합계',difference:'시간 차이'};
 function recordCard(e:Row){return <article className="record" key={e.id}><div className="section-head"><strong>{data.tasks.find(t=>t.id===e.task_id)?.title}</strong><b>{e.minutes}분</b></div><p>{dateTime(e.start_at)} → {dateTime(e.end_at)}</p>{e.note&&<p className="record-note">{e.note}</p>}{e.blocked&&<p className="blocked">막힌 이유 · {e.blocked}</p>}<div className="section-head"><details className="record-id"><summary>기록 정보</summary><small>ID {e.id}</small></details><button disabled={busy} onClick={()=>editLog(e)}><Pencil size={15}/> 기록 수정</button></div></article>}
 return <div className="shell"><header className="top"><div className="brand"><span className="brand-icon"><Leaf/></span><div>큐티스트릿도 <strong>다이어리</strong><small>MY LITTLE ISLAND JOURNAL</small></div></div><button onClick={exportAll} disabled={!loaded}><Download size={16}/> 내 자료 내보내기</button></header><p className="notice">지금은 로그인이 없어 링크를 아는 사람은 누구나 볼 수 있습니다. 남이 봐도 괜찮은 내용만 넣으세요</p><main><section className="welcome"><div><span className="eyebrow">유미의 주말 섬 생활</span><h1>이번 주말, 우리 섬.</h1><p>이번 주말의 작은 계획이 다음 주말의 풍경이 되도록.</p></div><div className="passport-photo"><img src="/photos/passport.png" alt="큐티스트릿도 주민 대표 유미의 여권"/></div></section><nav aria-label="다이어리 단계">{['계획과 할 일','플레이 기록','돌아보기'].map((name,i)=><button key={name} className={tab===i?'active':''} onClick={()=>{setTab(i);setDrill('')}} aria-current={tab===i?'page':undefined}>0{i+1} <span>{name}</span></button>)}</nav>
 {error&&<div className="error" role="alert">{error} <button onClick={load} disabled={busy}>다시 불러오기</button></div>}{toast&&<div className="toast" role="status">{toast}</div>}
 {!loaded?<section className="paper empty">{error?'연결되면 저장된 내용을 다시 보여 드릴게요.':'섬의 기록을 불러오고 있어요…'}</section>:plan&&<><div className="plan-switch"><label>보고 있는 계획 <select value={plan.id} onChange={e=>choosePlan(e.target.value)}>{data.plans.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label><button onClick={()=>setModal({kind:'plan-create',value:newPlan()})}><Plus size={16}/> 새 계획</button></div><details className="routine-panel"><summary>매일 섬 루틴 <span>날짜별로 다섯 가지 할 일 꺼내기</span></summary><div className="routine-content"><div className="plan-switch"><label>매일 섬 루틴 · 플레이할 날짜 <input aria-label="루틴 날짜" type="date" required value={routineDate} onChange={e=>setRoutineDate(e.target.value)}/></label><button disabled={busy||!routineDate} onClick={openRoutine}><Plus size={16}/> 다섯 가지 루틴 열기</button></div><p className="sort-note">플레이하는 날만 열어 주세요. 같은 날짜를 다시 열면 기존 기록이 이어져요. 예상 시간은 총 45분이며 직접 바꿀 수 있어요.</p><details><summary>다섯 가지 루틴 안내</summary><p>메시지 보틀 · 마일리지+ 미션 5개 · 주민 선물 · 호텔 명물 DIY 납품 · DIY 중인 주민에게 레시피 받기</p><p>호텔은 요청받은 명물을 만들어 납품해요. 재료나 레시피가 없으면 막힌 이유로 남겨 주세요. 주민 선물은 선물 대화가 열리는 주민에게, 레시피는 집에서 DIY 중인 주민에게 받아요.</p><a href="https://www.nintendo.com/kr/switch/acbaa/updates.html" target="_blank" rel="noreferrer">호텔 납품·쿠폰 안내 · 닌텐도</a> · <a href="https://nookipedia.com/wiki/DIY_recipes" target="_blank" rel="noreferrer">레시피 얻는 방법 · Nookipedia</a></details></div></details><div className="workspace"><section className="paper">
 {tab===0&&<><div className="section-head"><div><span className="eyebrow">PLAN · 이번에 만들 풍경</span><h2>{plan.title}</h2></div><button aria-label="계획 수정" onClick={()=>setModal({kind:'plan-edit',value:{...plan}})}><Pencil size={16}/> 수정</button></div><p>{plan.success}</p><div className="chips"><span>{plan.start_date} ~ {plan.end_date}</span><span>우선순위 {priority[plan.priority]}</span><span>계획 예상 {plan.estimate}분</span></div>{plan.improvement&&<p className="carry">지난 돌아보기에서 가져온 한 줄<br/><strong>{plan.improvement}</strong></p>}<details className="history"><summary><History size={15}/> 처음 계획과 수정 이력 ({data.plan_revisions.filter(r=>r.plan_id===plan.id).length})</summary><small>계획 ID {plan.id}</small>{data.plan_revisions.filter(r=>r.plan_id===plan.id).map(r=>{const s=JSON.parse(r.snapshot);return <div key={r.id}><b>{r.version===1?'처음 세운 계획':`${r.version}번째 버전`}</b><p>{s.title} · {s.start_date} ~ {s.end_date}<br/>우선순위 {priority[s.priority]} · 예상 {s.estimate}분<br/>{s.success}</p></div>})}</details><div className="progress-label"><span>{allStats.done===0?'아직 시작 전이에요':`${allStats.done}개의 할 일을 마쳤어요`}</span><strong>{allStats.done} / {tasks.length}</strong></div><div className="progress"><i style={{width:(tasks.length?allStats.done/tasks.length*100:0)+'%'}}/></div><div className="section-head task-heading"><h3>할 일</h3><button className="primary" onClick={()=>openTask()}><Plus size={16}/> 할 일 추가</button></div><details className="filter-panel"><summary>검색·필터 <span>{search||filter!=='all'||prio!=='all'||tag!=='all'?`적용 중 · ${visible.length}개 표시`:'필요할 때 펼치기'}</span></summary><div className="filters"><label className="search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="할 일·태그 검색" aria-label="할 일 검색"/></label><select aria-label="상태 필터" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">모든 상태</option><option value="open">진행 중</option><option value="done">완료</option><option value="late">지연</option></select><select aria-label="우선순위 필터" value={prio} onChange={e=>setPrio(e.target.value)}><option value="all">모든 우선순위</option>{[1,2,3].map(n=><option key={n} value={n}>{priority[n]}</option>)}</select><select aria-label="태그 필터" value={tag} onChange={e=>setTag(e.target.value)}><option value="all">모든 태그</option>{tags.map(t=><option key={t as string}>{t as string}</option>)}</select><select aria-label="정렬 기준" value={sort} onChange={e=>setSort(e.target.value)}><option value="due">마감일 빠른 순</option><option value="priority">우선순위 높은 순</option><option value="estimate">예상 시간 짧은 순</option></select></div></details><p className="sort-note">정렬: {sort==='due'?'마감일 빠른 순':sort==='priority'?'우선순위 높은 순':'예상 시간 짧은 순'} → 같으면 생성 시각 → ID 오름차순</p><div className="tasklist">{visible.map(t=><div className={'taskrow '+(t.status==='done'?'done':'')} key={t.id}><button className="check" disabled={busy} aria-label={t.title+(t.status==='done'?' 진행 중으로 되돌리기':' 완료 기록 남기기')} onClick={()=>t.status==='done'?mutate({op:'task-reopen',id:t.id}):openLog(t,true)}>{t.status==='done'&&<Check size={16}/>}</button><div className="tasktext"><strong>{t.title}</strong><small>{t.due_date} · {t.estimate}분 · {priority[t.priority]} · {t.status==='done'?'완료':'진행 중'}</small>{t.tags&&<span className="tag">{t.tags}</span>}</div><details className="task-menu"><summary aria-label={t.title+' 더 보기'}>···</summary><div className="actions"><button aria-label={t.title+' 실행 기록'} title="실행 기록" onClick={()=>openLog(t)}><Clock size={16}/> 기록</button><button aria-label={t.title+' 수정'} title="수정" onClick={()=>openTask(t)}><Pencil size={16}/> 수정</button><button aria-label={t.title+' 삭제'} title="삭제" onClick={()=>setModal({kind:'delete',value:t})}><Trash2 size={16}/> 삭제</button></div></details></div>)}{!visible.length&&<p className="empty">조건에 맞는 할 일이 없어요.</p>}</div></>}
 {tab===1&&<><div className="section-head"><div><span className="eyebrow">DO · 실제로 보낸 시간</span><h2>오늘 섬에서는 무슨 일이?</h2></div><button className="primary" onClick={()=>openLog()}><Plus size={16}/> 기록 남기기</button></div><p>시간은 서울 기준, 걸린 시간은 분으로 기록해요. 원래 예상 시간은 그대로 남아요.</p><div className="record-summary">실제 기록 <strong>{records.length}건</strong> · 실제 플레이 <strong>{playMinutes(records)}분</strong><p className="sort-note">겹친 시간을 한 번만 계산했어요. 기록별 시간 합계는 {allStats.actual}분이에요.</p></div>{records.length?records.map(recordCard):<div className="empty"><BookOpen size={32}/><h3>첫 플레이를 기다리는 중</h3><p>플레이한 뒤 시작·종료 시각과 한 일을 남겨 주세요.<br/>아직 하지 않은 일을 기록할 필요는 없어요.</p><button onClick={()=>openLog()}>첫 기록 남기기</button></div>}</>}
 {tab===2&&<><span className="eyebrow">SEE · 다음 주말을 위한 메모</span><h2>계획과 실제, 나란히 보기</h2><div className="range"><label>마감일 시작<input type="date" value={from} onChange={e=>{setFrom(e.target.value);setDrill('')}}/></label><span>~</span><label>마감일 끝<input type="date" value={to} min={from} onChange={e=>{setTo(e.target.value);setDrill('')}}/></label></div><p className="sort-note">선택한 계획에서 이 기간에 마감인 할 일을 모아요. 삭제한 할 일은 제외하고, 해당 할 일의 모든 실행 시간을 더해요. 숫자를 누르면 근거를 볼 수 있어요.</p>{from>to&&<p role="alert">종료일을 시작일 이후로 선택해 주세요.</p>}<div className="stats">{['planned','done','late','blocked'].map(k=><button key={k} className={drill===k?'selected':''} onClick={()=>setDrill(k)}><span>{labels[k]}</span><strong>{(stats as any)[k]}<small>개</small></strong></button>)}</div><div className="record-summary">겹친 시간 제외 · 실제 플레이 <strong>{playMinutes(stats.records)}분</strong><p className="sort-note">아래 기록별 시간 합계는 각 기록의 시간을 모두 더한 값이에요.</p></div><div className="times">{['estimate','actual','difference'].map(k=><button key={k} className={drill===k?'selected':''} onClick={()=>setDrill(k)}><span>{labels[k]}</span><strong>{k==='difference'&&stats.difference>0?'+':''}{(stats as any)[k]}<small>분</small></strong></button>)}</div><p className="sort-note">시간 차이 = 실제 − 예상 · 지연: 서울 기준 오늘({seoulToday()}) 이전 마감인 미완료 할 일 · 막힘: 이유가 적힌 할 일 수</p>
 {drill&&<section className="drill"><div className="section-head"><h3>{labels[drill]}의 근거</h3><button onClick={()=>setDrill('')} aria-label="근거 닫기"><X size={16}/></button></div>{drill!=='actual'&&drillTasks.map(t=><div className="evidence" key={t.id}><button onClick={()=>setModal({kind:'evidence',value:t})}>{t.title} <ArrowUpRight size={15}/></button><span>{t.status==='done'?'완료':'진행 중'} · 예상 {t.estimate}분</span></div>)}{(drill==='actual'||drill==='difference')&&stats.records.map(recordCard)}{(drill==='actual'?stats.records.length===0:drillTasks.length===0)&&<p>해당 기록이 없어 0이에요.</p>}</section>}
 <section className="next-plan"><h3>다음 계획에는 이렇게 해 볼래요</h3><p>고칠 점 한 줄을 새 계획에 가져가요.</p><button className="primary" onClick={()=>setModal({kind:'review',value:{...newPlan(),title:plan.title+' · 다음 계획',template:plan.id,priority:plan.priority,success:plan.success,estimate:plan.estimate,review_id:uid()}})}>돌아보고 다음 계획 세우기 <ArrowUpRight size={16}/></button>{data.reviews.filter(r=>r.plan_id===plan.id).map(r=><div className="carry" key={r.id}><p>{r.improvement}</p><button onClick={()=>{choosePlan(r.next_plan_id);setTab(0)}}>이어진 계획 보기 <ArrowUpRight size={15}/></button></div>)}</section></>}
 </section><aside><figure className="photo-card"><img src={tab===2?'/photos/room.jpg':'/photos/street.jpg'} alt={tab===2?'파란 방에서 쉬는 주민':'옷가게 앞 돌길과 주민'}/><figcaption>{tab===2?'잠깐 쉬면서 돌아보기':'우리 섬의 다음 풍경'}<small>{tab===2?'다음 주말의 나에게 남기는 한 줄':'유럽풍 거리, 작은 광장 그리고 두 가게'}</small></figcaption></figure><figure className="photo-card neighbors-card"><img src="/photos/neighbors.jpg" alt="광장에서 아이스크림을 먹는 세 주민"/><figcaption>큐티스트릿도 이웃들</figcaption></figure><div className="saved">서버에 저장된 기록 · {records.length}건<br/><button onClick={load}><RotateCcw size={14}/> 저장된 자료 다시 확인</button></div></aside></div></>}
 </main><footer><span>큐티스트릿도 다이어리</span><a href="https://github.com/youmjjang/plan_do_see" target="_blank" rel="noreferrer">소스 보기</a><span>PLAN · DO · SEE</span></footer>
 <dialog style={{transform:`translate(${offset.x}px, ${offset.y}px)`}} ref={dialog} onCancel={()=>{if(!busy)setModal(null)}} onClose={()=>{if(!busy)setModal(null)}}><div className="section-head dialog-handle" title="여기를 드래그해서 창 이동" onPointerDown={dragStart} onPointerMove={dragMove} onPointerUp={()=>{drag.current=null}} onPointerCancel={()=>{drag.current=null}} onLostPointerCapture={()=>{drag.current=null}}><h2>{modal?.kind==='execution-edit'?'플레이 기록 수정':modal?.kind==='execution'?'실제로 한 일 적기':modal?.kind==='delete'?'할 일 삭제':modal?.kind==='evidence'?'근거 기록':modal?.kind==='review'?'돌아보기 → 다음 계획':modal?.kind.startsWith('plan')?'내 계획': '할 일'}</h2><button type="button" disabled={busy} aria-label="창 닫기" onClick={()=>setModal(null)}><X/></button></div>
 {modal&&<>{error&&<div role="alert" className="error">{error}</div>}{modal.kind==='delete'?<><p>‘{modal.value.title}’을 삭제할까요? 집계에서 제외돼요. 기존 실행 기록은 전체 내보내기에 보관돼요.</p><button className="danger" disabled={busy} onClick={async()=>{if(await mutate({op:'task-delete',id:modal.value.id}))setModal(null)}}>삭제하기</button></>:modal.kind==='evidence'?<><h3>{modal.value.title}</h3><p>할 일 ID {modal.value.id}<br/>마감 {modal.value.due_date} · 예상 {modal.value.estimate}분 · {modal.value.status==='done'?'완료':'진행 중'}</p>{data.executions.filter(e=>e.task_id===modal.value.id).map(recordCard)}</>:<form onSubmit={submit}>
 {modal.kind.startsWith('execution')?<><label>어떤 할 일을 했나요?<select disabled={modal.kind==='execution-edit'} value={modal.value.task_id} onChange={e=>{const t=tasks.find(t=>t.id===e.target.value)!;setModal({...modal,value:{...modal.value,task_id:t.id,cycle:t.cycle,complete:t.status==='done'?false:modal.value.complete}})}}>{tasks.map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></label><div className="form-grid"><label>시작 시각 · 서울<input type="datetime-local" required value={modal.value.start_at} max={kstInput()} onChange={e=>change('start_at',e.target.value)}/></label><label>끝난 시각 · 서울<input type="datetime-local" required value={modal.value.end_at} min={modal.value.start_at} max={kstInput()} onChange={e=>change('end_at',e.target.value)}/></label></div>{modal.value.start_at&&modal.value.end_at&&<p>실제로 걸린 시간: {Math.round((Date.parse(modal.value.end_at+':00+09:00')-Date.parse(modal.value.start_at+':00+09:00'))/60000)}분</p>}<label>실제로 한 일<textarea maxLength={2000} value={modal.value.note} onChange={e=>change('note',e.target.value)} placeholder="실제로 진행한 내용을 적어 주세요"/></label><label>막혔던 이유 · 없으면 비워 둬요<textarea maxLength={1000} value={modal.value.blocked} onChange={e=>change('blocked',e.target.value)}/></label>{modal.kind==='execution'&&tasks.find(t=>t.id===modal.value.task_id)?.status!=='done'&&<label className="checkbox-label"><input type="checkbox" checked={modal.value.complete} onChange={e=>change('complete',e.target.checked)}/> 이 할 일을 완료로 바꾸기</label>}<p className="sort-note">실제 시간만 따로 저장해요. 계획의 예상 시간은 바뀌지 않아요.</p></>:<>
 {modal.kind==='review'&&<label>다음에 고칠 점 한 줄<textarea required maxLength={1000} value={modal.value.improvement} onChange={e=>change('improvement',e.target.value)} placeholder="직접 플레이하며 느낀 점을 적어 주세요"/></label>}
 {modal.kind==='review'?<><label>계획 이름<select value={modal.value.template||'custom'} onChange={e=>{const selected=data.plans.find(p=>p.id===e.target.value);setModal(m=>m?{...m,value:{...m.value,template:e.target.value,title:selected?selected.title+' · 다음 계획':'',...(selected?{priority:selected.priority,estimate:selected.estimate,success:selected.success}:{})}}:null)}}>{data.plans.map(p=><option key={p.id} value={p.id}>{p.title} 이어서</option>)}<option value="custom">직접 입력하기</option></select></label>{modal.value.template==='custom'?<label>새 계획 이름<input required maxLength={1000} value={modal.value.title} onChange={e=>change('title',e.target.value)}/></label>:<p className="sort-note">새 계획: {modal.value.title}<br/>기존 계획은 그대로 두고, 아래 기간으로 새 계획을 만들어요.</p>}</>:<label>{modal.kind.startsWith('task')?'할 일 이름':'계획 이름'}<input required maxLength={1000} value={modal.value.title} onChange={e=>change('title',e.target.value)}/></label>}<div className="form-grid">{modal.kind.startsWith('task')?<label>마감일<input required type="date" value={modal.value.due_date} onChange={e=>change('due_date',e.target.value)}/></label>:<><label>시작일<input required type="date" value={modal.value.start_date} onChange={e=>change('start_date',e.target.value)}/></label><label>종료일<input required type="date" min={modal.value.start_date} value={modal.value.end_date} onChange={e=>change('end_date',e.target.value)}/></label></>}<label>우선순위<select value={modal.value.priority} onChange={e=>change('priority',Number(e.target.value))}>{[1,2,3].map(n=><option key={n} value={n}>{priority[n]}</option>)}</select></label><label>예상 시간 · 분<input required type="number" min={0} max={100000} step={1} value={modal.value.estimate} onChange={e=>change('estimate',Number(e.target.value))}/></label></div>{modal.kind.startsWith('task')?<label>태그 · 쉼표로 구분<input maxLength={300} value={modal.value.tags} onChange={e=>change('tags',e.target.value)}/></label>:<label>성공 기준<textarea required maxLength={1000} value={modal.value.success} onChange={e=>change('success',e.target.value)} placeholder="무엇이 되면 이 계획을 마친 걸까요?"/></label>}</>}
 <div className="form-actions"><button type="button" disabled={busy} onClick={()=>setModal(null)}>취소</button><button className="primary" disabled={busy} type="submit">{busy?'저장하는 중…':modal.kind==='review'?'다음 계획으로 이어 저장':'저장하기'}</button></div></form>}</>}
 </dialog></div>
}

