:22px}.routine-panel>summary span,.filter-panel>summary span{display:block;margin-left:0;margin-top:4px}.task-menu[open] .actions button{padding:10px}.taskrow strong{font-size:15px}.taskrow small{font-size:13px}.routine-content .plan-switch{flex-wrap:wrap}.routine-content .plan-switch label{flex-basis:100%}}

