import { env } from "cloudflare:workers";
import { drizzle } from "drizzle-orm/d1";
import * as schema from "./schema";

export function getDb() {
  if (!env.DB) {
    throw new Error(
      "Cloudflare D1 binding `DB` is unavailable. Set the `d1` field in .openai/hosting.json to `DB` or let your control plane inject the real binding values before using the database."
    );
  }

  return drizzle(env.DB, { schema });
}

db/schema.ts.content:
import {sqliteTable,text,integer,index,uniqueIndex} from 'drizzle-orm/sqlite-core';
export const plans=sqliteTable('plans',{id:text('id').primaryKey(),title:text('title').notNull(),startDate:text('start_date').notNull(),endDate:text('end_date').notNull(),priority:integer('priority').notNull(),success:text('success').notNull(),estimate:integer('estimate').notNull(),improvement:text('improvement').notNull().default(''),version:integer('version').notNull().default(1),createdAt:text('created_at').notNull()});
export const revisions=sqliteTable('plan_revisions',{id:text('id').primaryKey(),planId:text('plan_id').notNull().references(()=>plans.id),version:integer('version').notNull(),snapshot:text('snapshot').notNull(),createdAt:text('created_at').notNull()},t=>[uniqueIndex('revision_plan_version').on(t.planId,t.version)]);
export const tasks=sqliteTable('tasks',{id:text('id').primaryKey(),planId:text('plan_id').notNull().references(()=>plans.id),title:text('title').notNull(),dueDate:text('due_date').notNull(),priority:integer('priority').notNull(),tags:text('tags').notNull().default(''),estimate:integer('estimate').notNull(),status:text('status').notNull().default('open'),cycle:integer('cycle').notNull().default(0),deletedAt:text('deleted_at'),createdAt:text('created_at').notNull()},t=>[index('tasks_plan_due').on(t.planId,t.dueDate)]);
export const executions=sqliteTable('executions',{id:text('id').primaryKey(),taskId:text('task_id').notNull().references(()=>tasks.id),startAt:text('start_at').notNull(),endAt:text('end_at').notNull(),minutes:integer('minutes').notNull(),blocked:text('blocked').notNull().default(''),note:text('note').notNull().default(''),completionKey:text('completion_key'),createdAt:text('created_at').notNull()},t=>[index('executions_task').on(t.taskId),uniqueIndex('execution_completion_key').on(t.completionKey)]);
export const completions=sqliteTable('completions',{id:text('id').primaryKey(),taskId:text('task_id').notNull().references(()=>tasks.id),cycle:integer('cycle').notNull(),createdAt:text('created_at').notNull()},t=>[uniqueIndex('completion_task_cycle').on(t.taskId,t.cycle)]);
export const reviews=sqliteTable('reviews',{id:text('id').primaryKey(),planId:text('plan_id').notNull().references(()=>plans.id),startDate:text('start_date').notNull(),endDate:text('end_date').notNull(),improvement:text('improvement').notNull(),nextPlanId:text('next_plan_id').notNull().references(()=>plans.id),createdAt:text('created_at').notNull()});

lib/pds.ts.content:
export type Row=Record<string,any>;
export type Data={plans:Row[];tasks:Row[];executions:Row[];plan_revisions:Row[];completions:Row[];reviews:Row[]};
export function seoulToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
export function selectTasks(data:Data,planId:string,from='',to=''){return data.tasks.filter(t=>!t.deleted_at&&t.plan_id===planId&&(!from||t.due_date>=from)&&(!to||t.due_date<=to))}
export function reviewStats(data:Data,tasks:Row[],today=seoulToday()){
 const ids=new Set(tasks.map(t=>t.id));const records=data.executions.filter(e=>ids.has(e.task_id));const blocked=new Set(records.filter(e=>e.blocked.trim()).map(e=>e.task_id));
 const estimate=tasks.reduce((n,t)=>n+t.estimate,0),actual=records.reduce((n,e)=>n+e.minutes,0);
 return {planned:tasks.length,done:tasks.filter(t=>t.status==='done').length,late:tasks.filter(t=>t.status!=='done'&&t.due_date<today).length,blocked:tasks.filter(t=>blocked.has(t.id)).length,estimate,actual,difference:actual-estimate,records};
}

lib/play-time.ts.content:
// Union of execution intervals; supplementary to the required sum of record minutes.
export function playMinutes(records: {start_at:string;end_at:string}[]) {
 const intervals=records.map(r=>[Date.parse(r.start_at),Date.parse(r.end_at)]).filter(([a,b])=>Number.isFinite(a)&&Number.isFinite(b)&&b>a).sort((a,b)=>a[0]-b[0]);
 let total=0,start=0,end=0;
 for(const [a,b] of intervals){if(a>end){total+=end-start;start=a;end=b}else end=Math.max(end,b)}
 return Math.round((total+end-start)/60000);
}

